.actionBtn {
  height: 28px;
  padding: 0 12px;
  border-radius: var(--bw-radius-hamburger);
  font-family: var(--bw-font-body);
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  color: var(--bw-ink-steel);
  background: none;
  border: 1px solid var(--bw-line-steel-strong);
  transition: border-color 0.12s, color 0.12s;
}

.actionBtn:hover:not(:disabled) {
  border-color: var(--bw-hover-border);
}

.dangerBtn:hover:not(:disabled) {
  border-color: var(--bw-badge-danger-border);
  color: var(--bw-sensitive-text);
}

.primaryBtn {
  height: 28px;
  padding: 0 12px;
  border-radius: var(--bw-radius-hamburger);
  font-family: var(--bw-font-body);
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  color: var(--bw-on-dark-hover);
  background: var(--bw-calibration-blue);
  border: none;
}

.primaryBtn:hover:not(:disabled) {
  background: var(--bw-primary-dark);
}

.renewBtn {
  height: 34px;
  padding: 0 16px;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  color: var(--bw-on-dark-hover);
  background: var(--bw-warning);
  border: none;
}

.renewBtn:hover:not(:disabled) {
  background: var(--bw-warning-dark);
}

.plainBtn {
  padding: 0;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  color: var(--bw-steel-mist);
  background: none;
  border: none;
}

.plainBtn:hover:not(:disabled) {
  color: var(--bw-sensitive-text);
}

.actionBtn:disabled,
.primaryBtn:disabled,
.renewBtn:disabled,
.plainBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

