/* SRCH-03 · Gestión de Watchers — panel de contenido.
   Ningún color literal: todo sale de los tokens `--bw-*` del design system. */

/*
 * La raíz de la pantalla es hija DIRECTA de `.bwcnt`, que es `overflow: hidden`
 * (F-186/F-189/F-190). Sin `flex: 1; min-height: 0; overflow-y: auto` la lista
 * se recorta sin barra de scroll con la ventana baja — el fallo que tuvieron las
 * seis pantallas anteriores de la corriente B.
 */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  letter-spacing: var(--bw-ls-eyebrow);
  text-transform: uppercase;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
