  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin: 0 0 6px;
}

.subtitle {
  font-family: var(--bw-font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin: 0 0 14px;
  max-width: 580px;
}

/* ── Aviso de éxito: uno solo a la vez, bajo el subtítulo. ── */
.notice {
