  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-error-text);
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  padding: 8px 12px;
  margin: 0 0 12px;
}

.counterRow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}

/* `X / 50 watchers activos`. Brass normal, rojo con el límite alcanzado (spec §6). */
