.chip {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  padding: 5px 13px;
  border-radius: 20px;
  cursor: pointer;
  color: var(--bw-steel-mist);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  transition: border-color 0.12s, color 0.12s;
}

.chip:hover {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.chipActive {
  color: var(--bw-on-dark-hover);
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
}

.chipCount {
  font-family: var(--bw-font-mono);
  font-weight: 500;
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.listItem {
  list-style: none;
}

/* ── Sin ningún watcher (spec §6). ── */
.empty {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--bw-radius);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
}

.emptyTitle {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-body);
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 6px;
}

.emptyHint {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin: 0;
}

/* ── Hay filas, pero ninguna en el chip activo. ── */
.emptyFilter {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-steel-mist);
  padding: 16px 0;
  margin: 0;
}

